const composeRoots = composeDirsAll.map((d) => d.replace(/\/+$/, ""));
const underComposeDir = (c: SrcContainer) =>
  c.mounts.some((m) => {
    const src = (m.source || "").replace(/\/+$/, "");
    return !!src && composeRoots.some((r) => src === r || src.startsWith(r + "/"));
  });
// A container whose compose working-dir label points at one of the dirs the
// engine is bringing up belongs to that project — exclude it even if its
// project-NAME label came back empty (same label set, but a stale/partial
// inspect can drop one and keep another).
const composeWdOwned = (c: SrcContainer) => {
  const wd = (c.composeWd || "").replace(/\/+$/, "");
  return !!wd && composeRoots.includes(wd);
};
// BUG 2: also exclude any container whose NAME is a container_name owned by a
// compose project we brought up (`composeOwnedNames`, gathered during the
// bring-up loop). This is what catches a compose DB container (e.g. a
// containerised `mongo`) whose project label came back EMPTY and whose datadir
// is a NAMED volume — neither `!c.project`, `underComposeDir`, nor
// `composeWdOwned` would exclude it, so it used to be wrongly recreated
// standalone and clash on name/port with the compose-managed one.
const standalone = srcContainers.filter((c) =>
  !c.project && !underComposeDir(c) && !composeWdOwned(c) && !composeOwnedNames.has(c.name)
);
